set -e
WS=/home/joao/projects/lean-pi/bench/out/four-way-20260921/attempts/claude-code-r2/workspace
rm -rf /tmp/before && mkdir -p /tmp/before
git -C "$WS" show HEAD:index.js > /tmp/before/index.js
cp "$WS/overridable-replacements.js" /tmp/before/
ln -s "$WS/node_modules" /tmp/before/node_modules
cat > /tmp/verify.mjs <<'EOF'
const [before, after] = [
  '/tmp/before/index.js',
  '/home/joao/projects/lean-pi/bench/out/four-way-20260921/attempts/claude-code-r2/workspace/index.js',
];

const words = ['foo','bar','example','Foo','Bar','section','Section'];
const rand = n => Math.floor(Math.random()*n);
const mk = () => {
  const w = words[rand(words.length)];
  switch (rand(6)) {
    case 0: return `${w} ${1+rand(3)}`;
    case 1: return `${w}-${1+rand(3)}`;
    case 2: return w;
    case 3: return `${w} bar`;
    case 4: return `${w}-${1+rand(2)}-${1+rand(2)}`;
    default: return `${w} ${1+rand(2)} ${1+rand(2)}`;
  }
};

const optionSets = [undefined, {lowercase: false}, {decamelize: false}, {separator: '_'}, {preserveLeadingUnderscore: true}, {transliterate: false}];
const sequences = [];
for (let i = 0; i < 4000; i++) {
  sequences.push([optionSets[rand(optionSets.length)], Array.from({length: 8}, mk)]);
}

const dupesFor = async module => {
  const {slugifyWithCounter} = await import(module);
  let bad = 0;
  let example = null;
  for (const [options, inputs] of sequences) {
    const counter = slugifyWithCounter();
    const seen = new Set();
    for (const input of inputs) {
      const out = counter(input, options);
      if (out && seen.has(out)) { bad++; if (!example) example = {input, out, inputs}; }
      if (out) seen.add(out);
    }
  }
  return {bad, example};
};

const b = await dupesFor(before);
const a = await dupesFor(after);
console.log(`before fix: ${b.bad} duplicate slugs over ${sequences.length} sequences`);
console.log('  example:', JSON.stringify(b.example?.inputs), '->', JSON.stringify(b.example?.out), 'twice');
console.log(`after fix:  ${a.bad} duplicate slugs over ${sequences.length} sequences`);

const {slugifyWithCounter} = await import(after);
const repro = slugifyWithCounter();
const outs = ['foo', 'foo', 'foo-2'].map(x => repro(x));
console.log('repro after:', JSON.stringify(outs), 'unique:', new Set(outs).size === outs.length);
console.log('same title twice:', JSON.stringify([repro('Example'), repro('Example'), repro('Example')]));
EOF
node /tmp/verify.mjs

